#include "stdio.h"
#include "string.h"
#include "interrupt.h"
#include "linux/errno.h"
#include "gx_mtc.h"
#include "version_autogenerated.h"

static int open_flag = 0;
gx_mtc_extra mtc_extra = {
	.isrvec = 48,
};

static int mtc_get_capability(struct mtc_capability *cap)
{
	if (!cap) {
		MTC_DBG ("%s, %d, invalid parameter\n", __func__, __LINE__);
		return -1;
	}

#if defined(CONFIG_ARCH_CKMMU_GX3211) || defined(CONFIG_ARCH_CKMMU_GX6605S) || defined(CONFIG_ARCH_CKMMU_GX3113C)
			cap->have_mtc  = 1;
			cap->algo_sup |= GXMTC_CAP_DES;
			cap->algo_sup |= GXMTC_CAP_3DES;
			cap->algo_sup |= GXMTC_CAP_AES128;
			cap->algo_sup |= GXMTC_CAP_AES192;
			cap->algo_sup |= GXMTC_CAP_AES256;
#else
			cap->have_mtc = 0;
#endif

	return 0;
}

int mtc_encrypt_and_decrypt(struct mtc_data_s *mtc_data)
{
	int ret = -EIO;

#if defined(CONFIG_ARCH_CKMMU_GX3211) || defined(CONFIG_ARCH_CKMMU_GX6605S)
	if (mtc_data->work_mode == GXMTC_DATA_DECRYPT_MODE) {
		if (mtc_data->mtc_key.key_from == GXMTC_KEY_FROM_SOFT)
			ret = gx_mtc_core_data_decrypt(mtc_data);
		else if (mtc_data->mtc_key.key_from == GXMTC_KEY_FROM_NDS)
			ret = gx_mtc_core_nds_decrypt(mtc_data);
		else if (mtc_data->mtc_key.key_from == GXMTC_KEY_FROM_OTP)
			ret = gx_mtc_core_otp_decrypt(mtc_data);
	} else if (mtc_data->work_mode == GXMTC_DATA_ENCRYPT_MODE) {
		if (mtc_data->mtc_key.key_from == GXMTC_KEY_FROM_SOFT)
			ret = gx_mtc_core_data_encrypt(mtc_data);
		else if (mtc_data->mtc_key.key_from == GXMTC_KEY_FROM_NDS)
			ret = gx_mtc_core_nds_encrypt(mtc_data);
		else if (mtc_data->mtc_key.key_from == GXMTC_KEY_FROM_OTP)
			ret = gx_mtc_core_otp_encrypt(mtc_data);
	} else if (mtc_data->work_mode == GXMTC_CW_DECRYPT_MODE) {
		ret = gx_mtc_core_cw_decrypt(mtc_data);
	} else if (mtc_data->work_mode == GXMTC_NDS_KEY_GENERATE_MODE) {
		ret = gx_mtc_nds_key_generate(mtc_data);
	}
#elif defined(CONFIG_ARCH_CKMMU_GX3113C)
	if (mtc_data->work_mode == GXMTC_DATA_DECRYPT_MODE)
		ret = gx_mtc_core_data_decrypt(mtc_data);
	else if (mtc_data->work_mode == GXMTC_DATA_ENCRYPT_MODE)
		ret = gx_mtc_core_data_encrypt(mtc_data);
	else if (mtc_data->work_mode == GXMTC_CW_DECRYPT_MODE)
		ret = gx_mtc_core_cw_decrypt(mtc_data);
#endif
	return ret;
}

int gx_mtc_ioctl(uint32_t key, void *buf)
{
	struct mtc_data_s *p_mtc_data;
	struct mtc_capability *cap;
	int ret = 0;

	switch (key) {
		case MTC_DO_WORK:
			p_mtc_data = (struct mtc_data_s *)buf;
			if (p_mtc_data)
				ret = mtc_encrypt_and_decrypt(p_mtc_data);
			break;
		case MTC_GET_CAP:
			cap = (struct mtc_capability *)buf;
			if (!cap) {
				MTC_DBG ("%s, invalid parameter\n", __func__);
				ret = -1;
				break;
			}
			memset(cap, 0, sizeof(struct mtc_capability));
			ret = mtc_get_capability(cap);
			break;
		default:
			break;
	}
	return ret;
}

int gx_mtc_close(void)
{
	if (!open_flag)
		return 0;

	gx_mtc_extra *extra = &mtc_extra;
	extra->sync_flag = 0;
#ifdef CONFIG_ENABLE_IRQ
	gx_free_interrupt(extra->isrvec);
#endif
	extra->result = GXMTC_DEFAULT_STATUS;
	open_flag = 0;

	return 0;
}

int gx_mtc_open(void)
{
	if (open_flag)
		return 0;

	gx_mtc_extra *extra = &mtc_extra;

	extra->sync_flag = 0;
#ifdef CONFIG_ENABLE_IRQ
	gx_request_interrupt(extra->isrvec, IRQ, mtc_interrupt_isr, extra);
#endif
	open_flag = 1;

	return 0;
}
